gpu.module @kernels {
  gpu.func @kernel(%arg: memref<1024xf32, 1>) kernel {
    %tid = gpu.thread_id x
    %bid = gpu.block_id  x
    %idx = arith.addi %bid, %tid : index
    %v   = memref.load %arg[%idx] : memref<1024xf32, 1>
    gpu.return
  }
}

func.func @host(%a: memref<1024xf32, 1>) {
  %c1  = arith.constant 1  : index
  %c256 = arith.constant 256 : index
  %c4   = arith.constant 4   : index
  gpu.launch_func @kernels::@kernel
     blocks in (%c4, %c1, %c1)
     threads in (%c256, %c1, %c1)
     args(%a : memref<1024xf32, 1>)
  return
}
